create extension if not exists vector;

create table note_chunks (
  id bigint generated always as identity primary key,
  note_id uuid not null references notes(id) on delete cascade,
  user_id uuid not null references auth.users(id),
  content text not null,
  embedding vector(1024) -- must match your model's size
);

const sources = chunks
  .map((c) => `<source id="${c.note_id}">\n${c.content}\n</source>`)
  .join("\n");

const prompt = `${sources}

Answer the question using only the sources above.
Cite source ids. If they do not answer it, say so.

Question: ${question}`;
